            code: 'one',
            type: 'one',
            content: 'store://bin',
            enabled: true,
            version: 1,
        );
        $other = new ThemeAsset(
            uid: 'other',
            theme: new ThemeRef('other'),
            code: 'other',
            type: 'other',
            content: 'store://obin',
